// === Tab: mySketch ===
let particles;

function setup() {
	let colourCodes = [
		"#556270",
		"#4ecdc4",
		"#c7f464",
		"#ff6b6b",
		"#c44d58"
	];

	createCanvas(1112, 834);
	background(100);
	particles = [];
	for (let i = 0; i < 200; i++) {
		let p = {
			x: random(0, width),
			y: random(0, height),
			speed: random(1, 5),
			size: random(10, 50),
			colour: random(colourCodes)
		};
		particles.push(p);
	}
	window.simulatedMouseX = width / 2;
	window.simulatedMouseY = height / 2;
}

function draw() {
	background('white');

	// draw all particles
	for (let p of particles) {
		fill(p.colour);

		circle(p.x, p.y, p.size);
		if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), p.x, p.y) < 300) {
			line((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), p.x, p.y);
		}
	}


	//move all particles
	for (let p of particles) {
		p.x = p.x + p.speed;
		if (p.x > width) {
			p.speed = p.speed * -1;
		}
		if (p.x < 0) {
			p.speed = p.speed * -1;
		}
	}
}

function keyPressed(){save('pix.jpg');}

